/**
 * The colour swap (docs/hero-looks.md §5.2, §12): the region recoloured and
 * nothing outside it, the painted shading kept, the near-grey, gamut and
 * clamping cases; her two parts recoloured each on its own and nothing
 * outside both; gold over her whole figure, her colours ignored; and the
 * reference sheet regenerated by the review tinter (tools/art/coat.py) and
 * compared with this one, a step of 8-bit apart at most.
 */

import { execFileSync } from "node:child_process";
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { describe, expect, it } from "vitest";
import type { CoatPaint } from "@kad/shared";
import { COAT_SWAP, FIGURE_FROM_ALPHA, MASK_CHANNEL, coatRegionStats, coatTarget, heroRegionStats, swapLightness, swapPixel, tintCoatPixels, tintHeroPixels, type HeroMask } from "./hero-coat";
import { runTint, slicedTintRunner } from "./hero-coat-pass";
import { hexToOklab, inGamut, oklabDistance, oklabToLinear, srgbToOklab } from "./oklab";
import { pixelIO, regionMean, servePainting, syntheticPainting } from "../testing/coat-fixture";

const labOf = (px: ArrayLike<number>, i: number) => srgbToOklab(px[i]! / 255, px[i + 1]! / 255, px[i + 2]! / 255);

function tinted(body: string, color: string, size = 24) {
  const { painting, mask } = syntheticPainting(body, size);
  const stats = coatRegionStats(painting.data, mask.data, 4);
  const out = new Uint8ClampedArray(painting.data.length);
  tintCoatPixels(painting.data, mask.data, color, stats, out, { maskStride: 4 });
  return { painting, mask, stats, out };
}

describe("the colour swap (§5.2)", () => {
  it("recolours the region and leaves everything outside it as painted, alpha untouched", () => {
    const { painting, mask, out } = tinted("#E2CDEC", "#3E6ADF");
    let inside = 0;
    for (let p = 0; p < 24 * 24; p++) {
      const i = p * 4;
      expect(out[i + 3]).toBe(painting.data[i + 3]);
      if (mask.data[i] === 0) {
        expect([out[i], out[i + 1], out[i + 2]]).toEqual([painting.data[i], painting.data[i + 1], painting.data[i + 2]]);
      } else if (mask.data[i] === 255) {
        inside += 1;
        // Fully masked: the coat's hue, not the lavender's.
        const [, a, b] = labOf(out, i);
        expect(Math.abs(Math.atan2(b, a) - Math.atan2(hexToOklab("#3E6ADF")[2], hexToOklab("#3E6ADF")[1]))).toBeLessThan(0.05);
      }
    }
    expect(inside).toBeGreaterThan(50);
    // The region's mean is the coat, near enough to read as it.
    expect(oklabDistance(regionMean(out, mask.data), hexToOklab("#3E6ADF"))).toBeLessThan(0.06);
  });

  it("keeps the painted shading: each pixel's step from the region's anchor, softened going dark", () => {
    // A mid colour, well inside the floor and ceiling, on a narrow region: the steps as painted.
    const mid = tinted("#E2CDEC", "#E0508F");
    const dark = tinted("#E2CDEC", "#3E1D6B");
    expect(mid.stats.highL - mid.stats.lowL).toBeLessThan(COAT_SWAP.span);
    const target = { mid: hexToOklab("#E0508F")[0], dark: hexToOklab("#3E1D6B")[0] };
    for (let p = 0; p < 24 * 24; p++) {
      const i = p * 4;
      if (mid.mask.data[i] !== 255) continue;
      const step = labOf(mid.painting.data, i)[0] - mid.stats.anchorL;
      // Going lighter than the region the step is kept as painted...
      expect(labOf(mid.out, i)[0] - target.mid).toBeCloseTo(step, 1);
      // ...going darker it is softened (×0.85), never flattened.
      expect(labOf(dark.out, i)[0] - target.dark).toBeCloseTo(step * COAT_SWAP.darkSoften, 1);
    }
    // A highlight stays lighter than a shadow, whatever the colour.
    const light = tinted("#E2CDEC", "#E8F0FF");
    const order = (o: Uint8ClampedArray) => labOf(o, (8 * 24 + 8) * 4)[0] > labOf(o, (16 * 24 + 16) * 4)[0];
    expect(order(light.out) && order(dark.out) && order(mid.out)).toBe(true);
  });

  it("anchors on the region's median lightness, not its mean", () => {
    const stats = coatRegionStats(new Uint8ClampedArray([230, 230, 230, 255, 230, 230, 230, 255, 40, 40, 40, 255]), new Uint8ClampedArray([255, 255, 255]));
    // Two light pixels and a dark one: the anchor is the light ones', the spread both.
    expect(stats.anchorL).toBeCloseTo(srgbToOklab(230 / 255, 230 / 255, 230 / 255)[0], 2);
    expect(stats.lowL).toBeCloseTo(srgbToOklab(40 / 255, 40 / 255, 40 / 255)[0], 2);
  });

  it("compresses a wide region's steps to fit, and keeps them off the floor and the ceiling", () => {
    const wide = { anchorL: 0.88, lowL: 0.3, highL: 0.95 };
    // Spread 0.65 > span: steps scaled by span / spread (and softened going darker).
    const k = COAT_SWAP.span / 0.65;
    expect(swapLightness(0.88, 0.6, wide)).toBeCloseTo(0.6, 6);
    expect(swapLightness(0.6, 0.6, wide)).toBeCloseTo(0.6 - 0.28 * k * COAT_SWAP.darkSoften, 6);
    // A dark colour: the darkest of the region stops at the floor, not black.
    expect(swapLightness(0.3, 0.29, wide)).toBeCloseTo(COAT_SWAP.floor, 6);
    // A light colour: the lightest stops at the ceiling, not clamped white.
    expect(swapLightness(0.95, 0.93, wide)).toBeCloseTo(COAT_SWAP.ceil, 6);
    expect(swapLightness(0.92, 0.93, wide)).toBeLessThan(COAT_SWAP.ceil);
    expect(swapLightness(0.92, 0.93, wide)).toBeGreaterThan(0.93);
  });

  it("varies chroma with the pixel's own, by the square root of its ratio to the anchor, clamped", () => {
    const stats = { anchorL: 0.7, lowL: 0.6, highL: 0.8, anchorC: 0.08, weight: 1 };
    const target = coatTarget("#3E6ADF");
    const chroma = (c: number) => {
      const [r, g, b] = swapPixel(0.7, c, target, stats);
      const [, a, bb] = srgbToOklab(r, g, b);
      return Math.hypot(a, bb);
    };
    expect(chroma(0.08)).toBeCloseTo(target.C, 2);
    expect(chroma(0.08 * 1.21)).toBeGreaterThan(chroma(0.08));
    expect(chroma(0.08 * 1.21) / chroma(0.08)).toBeCloseTo(1.1, 1);
    // Clamped to 0.6..1.4 of the coat's.
    expect(chroma(0) / target.C).toBeCloseTo(COAT_SWAP.minRatio, 1);
  });

  it("gives a near-grey region (a white coat) the coat's chroma flat", () => {
    const { mask, out, stats } = tinted("#F4F3F0", "#3E6ADF");
    expect(stats.anchorC).toBeLessThan(COAT_SWAP.greyChroma);
    const target = coatTarget("#3E6ADF");
    for (let p = 0; p < 24 * 24; p++) {
      const i = p * 4;
      if (mask.data[i] !== 255) continue;
      const [, a, b] = labOf(out, i);
      // Every pixel the coat's chroma (or as much as sRGB allows at its lightness).
      expect(Math.hypot(a, b)).toBeLessThanOrEqual(target.C + 0.01);
      expect(Math.hypot(a, b)).toBeGreaterThan(target.C * 0.5);
    }
  });

  it("brings an out-of-gamut colour in by chroma alone, keeping its lightness and hue", () => {
    const stats = { anchorL: 0.6, lowL: 0.45, highL: 0.7, anchorC: 0.05, weight: 1 };
    const target = coatTarget("#00FF40");
    // Far lighter than the coat, at the coat's full chroma: outside sRGB.
    expect(inGamut(oklabToLinear(0.95, target.C * target.cos, target.C * target.sin))).toBe(false);
    const [r, g, b] = swapPixel(0.6 + 0.1, 0.05, target, stats);
    const [L, a, bb] = srgbToOklab(r, g, b);
    expect(L).toBeCloseTo(swapLightness(0.7, target.L, stats), 2);
    expect(Math.atan2(bb, a)).toBeCloseTo(Math.atan2(target.sin, target.cos), 1);
    expect(Math.hypot(a, bb)).toBeLessThan(target.C);
  });

  it("clamps lightness to 0.04..0.98: nothing goes to pure black or blows out to white", () => {
    // A pixel outside the region's spread (its 5th..95th percentile) can still step past the ends.
    const stats = { anchorL: 0.5, lowL: 0.45, highL: 0.55, anchorC: 0.05, weight: 1 };
    const white = swapPixel(0.5 + 0.4, 0.05, coatTarget("#FFFFFF"), stats);
    const black = swapPixel(0.5 - 0.6, 0.05, coatTarget("#000000"), stats);
    expect(srgbToOklab(...white)[0]).toBeCloseTo(COAT_SWAP.maxL, 2);
    expect(srgbToOklab(...black)[0]).toBeCloseTo(COAT_SWAP.minL, 2);
  });

  it("blends by the mask, so a soft edge stays soft", () => {
    const { painting, mask, out } = tinted("#E2CDEC", "#20134E");
    const soft = [...Array(24 * 24).keys()].find((p) => mask.data[p * 4]! > 40 && mask.data[p * 4]! < 215)!;
    expect(soft).toBeDefined();
    const i = soft * 4;
    const was = labOf(painting.data, i)[0];
    const now = labOf(out, i)[0];
    // Part way from the painting to the coat, not all the way.
    expect(now).toBeLessThan(was);
    expect(now).toBeGreaterThan(hexToOklab("#20134E")[0]);
  });

  it("does the same pass in slices as in one go", async () => {
    const files = new Map();
    servePainting(files, "/assets/a.png", "#E2CDEC", 32);
    const job = { painting: "/assets/a.png", mask: "/assets/a.coat-mask.png", paint: { kind: "parts", main: "#77E2C5", accent: "#3E1D6B" } as CoatPaint };
    const whole = await runTint(job, pixelIO(files), new AbortController().signal, 1 << 20);
    const sliced = await slicedTintRunner(pixelIO(files), 50)(job, new AbortController().signal);
    expect((sliced.source as { data: Uint8ClampedArray }).data).toEqual((whole.source as { data: Uint8ClampedArray }).data);
  });

  it("draws an empty mask as painted", () => {
    const { painting } = syntheticPainting("#E2CDEC");
    const empty = new Uint8ClampedArray(painting.data.length);
    const stats = coatRegionStats(painting.data, empty, 4);
    const out = new Uint8ClampedArray(painting.data.length);
    tintCoatPixels(painting.data, empty, "#3E6ADF", stats, out, { maskStride: 4 });
    expect(out).toEqual(painting.data);
  });
});

// ---------------------------------------------------------------------------
// Two parts, and gold (owner, 2026-11-07)
// ---------------------------------------------------------------------------

/** Her whole look on a synthetic hero: an RGB mask, red the body, green the mane, blue the figure. */
function look(paint: CoatPaint, size = 32) {
  const { painting, mask } = syntheticPainting("#E2CDEC", size);
  const view: HeroMask = { data: mask.data, stride: 4, figure: MASK_CHANNEL.figure };
  const stats = heroRegionStats(painting.data, view);
  const out = new Uint8ClampedArray(painting.data.length);
  tintHeroPixels(painting.data, view, paint, stats, out);
  return { painting, mask, stats, out };
}

const hueOf = (lab: readonly number[]) => Math.atan2(lab[2]!, lab[1]!);
const hueOff = (a: readonly number[], hex: string) => {
  const d = Math.abs(hueOf(a) - hueOf(hexToOklab(hex)));
  return Math.min(d, 2 * Math.PI - d);
};

describe("her two parts (§5.2, two parts)", () => {
  it("recolours each part on its own, by its own region, and nothing outside both", () => {
    const both = look({ kind: "parts", main: "#3E6ADF", accent: "#F4D986" });
    let body = 0;
    let mane = 0;
    for (let p = 0; p < 32 * 32; p++) {
      const i = p * 4;
      const [r, g] = [both.mask.data[i]!, both.mask.data[i + 1]!];
      expect(both.out[i + 3]).toBe(both.painting.data[i + 3]);
      if (r === 0 && g === 0) {
        // Outside both parts (the outline, the ground): as painted.
        expect([both.out[i], both.out[i + 1], both.out[i + 2]]).toEqual([both.painting.data[i], both.painting.data[i + 1], both.painting.data[i + 2]]);
      } else if (r === 255) {
        body += 1;
        expect(hueOff(labOf(both.out, i), "#3E6ADF")).toBeLessThan(0.05);
      } else if (g === 255) {
        mane += 1;
        expect(hueOff(labOf(both.out, i), "#F4D986")).toBeLessThan(0.08);
      }
    }
    expect(body).toBeGreaterThan(50);
    expect(mane).toBeGreaterThan(10);
    // Each part's mean is its own colour.
    expect(oklabDistance(regionMean(both.out, both.mask.data, 4, MASK_CHANNEL.main), hexToOklab("#3E6ADF"))).toBeLessThan(0.06);
    expect(oklabDistance(regionMean(both.out, both.mask.data, 4, MASK_CHANNEL.accent), hexToOklab("#F4D986"))).toBeLessThan(0.08);
    // Its own region's means, not the figure's: the mane's are its own.
    expect(both.stats.accent.anchorL).not.toBeCloseTo(both.stats.main.anchorL, 2);
  });

  it("changes one part without the other: the main alone leaves the mane as painted, and the other way round", () => {
    const mainOnly = look({ kind: "parts", main: "#3E6ADF", accent: null });
    const accentOnly = look({ kind: "parts", main: null, accent: "#F4D986" });
    const both = look({ kind: "parts", main: "#3E6ADF", accent: "#F4D986" });
    for (let p = 0; p < 32 * 32; p++) {
      const i = p * 4;
      const px = (o: Uint8ClampedArray) => [o[i], o[i + 1], o[i + 2]];
      if (mainOnly.mask.data[i + 1] === 0) expect(px(accentOnly.out)).toEqual(px(accentOnly.painting.data));
      if (mainOnly.mask.data[i] === 0) expect(px(mainOnly.out)).toEqual(px(mainOnly.painting.data));
      // Where only one part reaches, the pair paints it as that part alone does.
      if (mainOnly.mask.data[i + 1] === 0) expect(px(both.out)).toEqual(px(mainOnly.out));
      if (mainOnly.mask.data[i] === 0) expect(px(both.out)).toEqual(px(accentOnly.out));
    }
  });

  it("never paints a pixel more than wholly where the parts' soft edges meet", () => {
    // Two weights that add to more than the whole pixel are shared out: the swap of each, by its share.
    const src = new Uint8ClampedArray([200, 180, 220, 255]);
    const mask = new Uint8ClampedArray([200, 200, 255, 255]);
    const view: HeroMask = { data: mask, stride: 4, figure: MASK_CHANNEL.figure };
    const stats = heroRegionStats(src, view);
    const out = new Uint8ClampedArray(4);
    tintHeroPixels(src, view, { kind: "parts", main: "#000000", accent: "#000000" }, stats, out);
    const alone = new Uint8ClampedArray(4);
    tintCoatPixels(src, new Uint8ClampedArray([255]), "#000000", stats.main, alone);
    // Half each of the same swap is the whole swap: none of the painting shows through.
    expect([...out].map((v, k) => Math.abs(v - alone[k]!) <= 1)).toEqual([true, true, true, true]);
  });
});

describe("gold (§5.5, gilded)", () => {
  it("ignores her colours and swaps her whole figure toward gold, keeping its lightness steps", () => {
    const gold = look({ kind: "gilded", color: "#E2B13C" });
    let figure = 0;
    for (let p = 0; p < 32 * 32; p++) {
      const i = p * 4;
      if (gold.mask.data[i + 2] === 0) {
        expect([gold.out[i], gold.out[i + 1], gold.out[i + 2]]).toEqual([gold.painting.data[i], gold.painting.data[i + 1], gold.painting.data[i + 2]]);
        continue;
      }
      figure += 1;
      // Every part of her, the outline and the mane included, is gold's hue now.
      expect(hueOff(labOf(gold.out, i), "#E2B13C")).toBeLessThan(0.15);
    }
    expect(figure).toBeGreaterThan(200);
    // The outline stays darker than the body: the statue keeps its shading.
    const edge = [...Array(32 * 32).keys()].find((p) => gold.mask.data[p * 4 + 2] === 255 && gold.mask.data[p * 4] === 0 && gold.mask.data[p * 4 + 1] === 0)!;
    const middle = (16 * 32 + 16) * 4;
    expect(labOf(gold.out, edge * 4)[0]).toBeLessThan(labOf(gold.out, middle)[0]);
  });

  it("on a cut-out painting with no mask, reads its alpha as her figure", async () => {
    const files = new Map();
    servePainting(files, "/assets/a/assembled.png", "#E2CDEC", 32, { mask: false });
    const paint: CoatPaint = { kind: "gilded", color: "#E2B13C" };
    const made = await runTint({ painting: "/assets/a/assembled.png", mask: null, paint }, pixelIO(files), new AbortController().signal);
    const { painting, mask } = syntheticPainting("#E2CDEC", 32);
    const view: HeroMask = { data: painting.data, ...FIGURE_FROM_ALPHA };
    const want = new Uint8ClampedArray(painting.data.length);
    tintHeroPixels(painting.data, view, paint, heroRegionStats(painting.data, view), want);
    expect((made.source as { data: Uint8ClampedArray }).data).toEqual(want);
    // The same as by the mask's blue channel, which is her alpha here.
    const byMask = look(paint);
    expect(want).toEqual(byMask.out);
    expect(mask.data.length).toBe(painting.data.length);
  });

  it("refuses an opaque painting with no mask, and her colours with no mask: drawn as painted", async () => {
    const files = new Map();
    const { painting } = syntheticPainting("#E2CDEC", 16);
    for (let i = 3; i < painting.data.length; i += 4) painting.data[i] = 255;
    files.set("/assets/gear.png", painting);
    servePainting(files, "/assets/a/assembled.png", "#E2CDEC", 16, { mask: false });
    const signal = new AbortController().signal;
    await expect(runTint({ painting: "/assets/gear.png", mask: null, paint: { kind: "gilded", color: "#E2B13C" } }, pixelIO(files), signal)).rejects.toThrow(/opaque/);
    await expect(runTint({ painting: "/assets/a/assembled.png", mask: null, paint: { kind: "parts", main: "#3E6ADF", accent: null } }, pixelIO(files), signal)).rejects.toThrow(/no coat mask/);
  });

  it("makes her figure an alpha mask, for the sparkles' clip over an opaque portrait", async () => {
    const files = new Map();
    servePainting(files, "/assets/a.png", "#E2CDEC", 16);
    const made = await runTint({ painting: "/assets/a.png", mask: "/assets/a.coat-mask.png", paint: { kind: "figure" } }, pixelIO(files), new AbortController().signal);
    const data = (made.source as { data: Uint8ClampedArray }).data;
    const { mask } = syntheticPainting("#E2CDEC", 16);
    for (let i = 0; i < data.length; i += 4) {
      expect([data[i], data[i + 1], data[i + 2]]).toEqual([255, 255, 255]);
      expect(data[i + 3]).toBe(mask.data[i + 2]);
    }
  });
});

// ---------------------------------------------------------------------------
// A part painted in two lightnesses (a Bigfoot's cream body and brown mane)
// ---------------------------------------------------------------------------

/**
 * One part, two very different lightnesses: a cream body over most of it (about 60%) and a dark
 * brown mane over the rest, every pixel of both in the part (red) at full weight, shaded as a
 * painted body is. The chosen colour must land on the larger area, the smaller a shade of it.
 */
function twoLightnessPart(size = 48) {
  const rgba = new Uint8ClampedArray(size * size * 4);
  const mask = new Uint8ClampedArray(size * size);
  const body: number[] = [];
  const mane: number[] = [];
  for (let y = 0; y < size; y++) {
    for (let x = 0; x < size; x++) {
      const p = y * size + x;
      const shade = 1.04 - 0.12 * ((x + y) / (2 * size));
      const isMane = y < size * 0.4;
      const [r, g, b] = isMane ? [118, 84, 58] : [242, 234, 225];
      rgba.set([Math.min(255, Math.round(r * shade)), Math.min(255, Math.round(g * shade)), Math.min(255, Math.round(b * shade)), 255], p * 4);
      mask[p] = 255;
      (isMane ? mane : body).push(p);
    }
  }
  return { rgba, mask, body, mane };
}

function areaMean(px: ArrayLike<number>, pixels: number[]) {
  const sum = [0, 0, 0];
  for (const p of pixels) {
    const lab = labOf(px, p * 4);
    for (let k = 0; k < 3; k++) sum[k]! += lab[k]!;
  }
  return sum.map((v) => v / pixels.length);
}

describe("a part painted in two lightnesses (§5.2)", () => {
  const part = twoLightnessPart();
  const stats = coatRegionStats(part.rgba, part.mask, 1);
  const tint = (color: string) => {
    const out = new Uint8ClampedArray(part.rgba.length);
    tintCoatPixels(part.rgba, part.mask, color, stats, out);
    return out;
  };

  it("lands the chosen colour on the larger area, the cream body, for a light, a dark, a grey and a saturated choice", () => {
    expect(part.body.length).toBeGreaterThan(part.mane.length);
    for (const color of ["#F7E9A8", "#23264A", "#9A9A9A", "#E8326E"]) {
      const out = tint(color);
      expect(oklabDistance(areaMean(out, part.body), hexToOklab(color)), color).toBeLessThan(0.04);
      // The mane: a darker shade of it.
      expect(areaMean(out, part.mane)[0]!, color).toBeLessThan(areaMean(out, part.body)[0]! - 0.05);
    }
  });

  it("keeps a dark choice's smaller area dark but not crushed, and a light choice's unclamped", () => {
    const dark = tint("#23264A");
    for (const p of part.mane) expect(labOf(dark, p * 4)[0]).toBeGreaterThanOrEqual(0.12);
    const light = tint("#F7E9A8");
    for (const p of [...part.body, ...part.mane]) expect(labOf(light, p * 4)[0]).toBeLessThan(COAT_SWAP.maxL - 0.01);
    // Its painted shading survives: the body is not one flat colour.
    const bodyL = part.body.map((p) => labOf(light, p * 4)[0]!);
    expect(Math.max(...bodyL) - Math.min(...bodyL)).toBeGreaterThan(0.02);
  });
});

// ---------------------------------------------------------------------------
// The reference sheet
// ---------------------------------------------------------------------------

const ART = fileURLToPath(new URL("../../../../tools/art/", import.meta.url));
const REFERENCE = JSON.parse(readFileSync(`${ART}fixtures/coat-reference.json`, "utf8")) as {
  size: number;
  coats: Record<string, string>;
  parts: Record<string, { main: string | null; accent: string | null }>;
  gilded: Record<string, string>;
  paintings: Record<string, { rgba: string; mask: string; tinted: Record<string, string>; parts: Record<string, string>; gilded: Record<string, string> }>;
};
const bytes = (b64: string) => new Uint8ClampedArray(Buffer.from(b64, "base64"));

function worstStep(a: ArrayLike<number>, b: ArrayLike<number>): number {
  let worst = 0;
  for (let i = 0; i < a.length; i++) worst = Math.max(worst, Math.abs(a[i]! - b[i]!));
  return worst;
}

describe("the reference sheet (tools/art/fixtures/coat-reference.json)", () => {
  it("is what the review tinter (coat.py) makes today: regenerated and compared", () => {
    const python = process.platform === "win32" ? "python" : "python3";
    let out: string;
    try {
      out = execFileSync(python, [`${ART}coat-reference.py`, "--check"], { encoding: "utf8", stdio: ["ignore", "pipe", "pipe"] });
    } catch (error) {
      const e = error as { stderr?: string; code?: string };
      if (e.code === "ENOENT") return; // no Python here: the committed sheet still holds the line below
      throw new Error(e.stderr ?? String(error));
    }
    expect(out).toContain("unchanged");
  });

  it("is matched by this tinter's single-mask call, a step of 8-bit at most, on every painting and test colour", () => {
    for (const [name, p] of Object.entries(REFERENCE.paintings)) {
      const rgba = bytes(p.rgba);
      const mask = bytes(p.mask);
      // The mask is RGB, 3 entries a pixel: the main part is red.
      const stats = coatRegionStats(rgba, mask, 3, 0);
      for (const [kind, color] of Object.entries(REFERENCE.coats)) {
        const out = new Uint8ClampedArray(rgba.length);
        tintCoatPixels(rgba, mask, color, stats, out, { maskStride: 3, maskOffset: 0 });
        expect(worstStep(out, bytes(p.tinted[kind]!)), `${name} in ${kind} ${color}`).toBeLessThanOrEqual(1);
      }
    }
  });

  it("is matched on both parts at once, each alone, and gold, a step of 8-bit at most", () => {
    expect(Object.keys(REFERENCE.parts).length).toBeGreaterThan(0);
    expect(Object.keys(REFERENCE.gilded).length).toBeGreaterThan(0);
    for (const [name, p] of Object.entries(REFERENCE.paintings)) {
      const rgba = bytes(p.rgba);
      const view: HeroMask = { data: bytes(p.mask), stride: 3, figure: MASK_CHANNEL.figure };
      const stats = heroRegionStats(rgba, view);
      for (const [kind, { main, accent }] of Object.entries(REFERENCE.parts)) {
        const out = new Uint8ClampedArray(rgba.length);
        tintHeroPixels(rgba, view, { kind: "parts", main, accent }, stats, out);
        expect(worstStep(out, bytes(p.parts[kind]!)), `${name} in ${kind}`).toBeLessThanOrEqual(1);
      }
      for (const [kind, color] of Object.entries(REFERENCE.gilded)) {
        const out = new Uint8ClampedArray(rgba.length);
        tintHeroPixels(rgba, view, { kind: "gilded", color }, stats, out);
        expect(worstStep(out, bytes(p.gilded[kind]!)), `${name} in ${kind}`).toBeLessThanOrEqual(1);
      }
    }
  });
});
